// Writes .env.local from the running local Supabase stack (`pnpm db:start` first).
// Usage: pnpm env:local
import { execSync } from "node:child_process";
import { existsSync, writeFileSync } from "node:fs";

const status = JSON.parse(execSync("pnpm exec supabase status -o json", { encoding: "utf8" }));
const lines = [
  "# Generated by scripts/env-from-supabase.mjs for the LOCAL stack. Never commit.",
  `NEXT_PUBLIC_SUPABASE_URL=${status.API_URL}`,
  `NEXT_PUBLIC_SUPABASE_ANON_KEY=${status.ANON_KEY}`,
  "NEXT_PUBLIC_TURNSTILE_SITE_KEY=",
  `SUPABASE_SERVICE_ROLE_KEY=${status.SERVICE_ROLE_KEY}`,
  "",
];
if (existsSync(".env.local") && !process.argv.includes("--force")) {
  console.error(".env.local exists; re-run with --force to overwrite.");
  process.exit(1);
}
writeFileSync(".env.local", lines.join("\n"), { mode: 0o600 });
console.log("Wrote .env.local");
